with a as(select * from public.authors where open_library_id=any(array['OL55572A','OL74490A','OL135196A','OL33242A','OL229073A','OL25714A']::text[])),w as(select * from public.works where open_library_id=any(array['OL1326348W','OL702797W','OL500451W','OL857544W','OL1912225W','OL22914W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789021494357','9789029507516','9789059361751','9789029077859','9789029504638','9789044313369']::text[]) or open_library_edition_id=any(array['OL25098875M','OL1785184M','OL39470733M','OL36631149M','OL35063156M','OL35606817M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987120001 and 987120999),'editions',(select count(*) from public.editions where id between 987220001 and 987220999),'authors',(select count(*) from public.authors where id between 987320001 and 987320999))) as preflight;
